{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "inventory",
      "host": "inventory.internal",
      "port": 9909,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 8932,
      "weight": 10,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 9861,
      "weight": 5,
      "health_check": "/healthz"
    },
    {
      "name": "pricing",
      "host": "pricing.internal",
      "port": 7727,
      "weight": 6,
      "health_check": "/healthz"
    },
    {
      "name": "legacy-billing",
      "host": "legacy-billing.internal",
      "port": 8189,
      "weight": 2,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/carts/tokens",
      "upstream": "carts",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 1500,
      "retries": 0
    },
    {
      "path": "/api/v1/catalog/history",
      "upstream": "catalog",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 2500,
      "retries": 1
    },
    {
      "path": "/api/v1/pricing/audit",
      "upstream": "pricing",
      "methods": [
        "GET",
        "PUT"
      ],
      "timeout_ms": 5000,
      "retries": 1
    },
    {
      "path": "/api/v1/inventory/events",
      "upstream": "inventory",
      "methods": [
        "POST"
      ],
      "timeout_ms": 1500,
      "retries": 3
    },
    {
      "path": "/api/v1/pricing/export",
      "upstream": "pricing",
      "methods": [
        "GET"
      ],
      "timeout_ms": 2500,
      "retries": 3
    },
    {
      "path": "/api/v1/carts/events",
      "upstream": "carts",
      "methods": [
        "GET",
        "POST",
        "PATCH"
      ],
      "timeout_ms": 1500,
      "retries": 2
    },
    {
      "path": "/api/v1/pricing/labels",
      "upstream": "pricing",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2500,
      "retries": 2
    },
    {
      "path": "/api/v1/pricing/batch",
      "upstream": "pricing",
      "methods": [
        "GET",
        "POST"
      ],
      "timeout_ms": 1000,
      "retries": 0
    },
    {
      "path": "/api/v1/inventory/settings",
      "upstream": "inventory",
      "methods": [
        "POST"
      ],
      "timeout_ms": 2000,
      "retries": 0
    }
  ]
}

